/* Generated by Claude Opus 5 (Anthropic)
 * Report the *allowed* CPU count (or FISH_NPROC) to anything that asks the
 * libc how many processors there are.  rclcpp's MultiThreadedExecutor sizes
 * its thread pool with std::thread::hardware_concurrency(), which on glibc is
 * sysconf(_SC_NPROCESSORS_ONLN) — the host's online CPUs, ignoring the
 * affinity mask a `taskset`/cpuset run confines it to. */
#define _GNU_SOURCE
#include <sched.h>
#include <unistd.h>
#include <dlfcn.h>
#include <stdlib.h>

static long real_sysconf(int name) {
    static long (*f)(int) = 0;
    if (!f) f = (long (*)(int)) dlsym(RTLD_NEXT, "sysconf");
    return f(name);
}

static long allowed_cpus(void) {
    const char *ov = getenv("FISH_NPROC");
    if (ov && *ov) { long v = atol(ov); if (v > 0) return v; }
    cpu_set_t m; CPU_ZERO(&m);
    if (sched_getaffinity(0, sizeof(m), &m) == 0) { int n = CPU_COUNT(&m); if (n > 0) return n; }
    return -1;
}

long sysconf(int name) {
    if (name == _SC_NPROCESSORS_ONLN || name == _SC_NPROCESSORS_CONF) {
        long n = allowed_cpus();
        if (n > 0) return n;
    }
    return real_sysconf(name);
}
int get_nprocs(void)      { return (int) sysconf(_SC_NPROCESSORS_ONLN); }
int get_nprocs_conf(void) { return (int) sysconf(_SC_NPROCESSORS_CONF); }
